code.src:
UPDATE TEMP SET DEGREE = DEGREE + 0.5;
DELETE FROM TEMP WHERE -SID = WEIGHT;
SELECT NAME, DEGREE, ROUND((DEGREE - 32) * 5 / 9, 2) AS CELSIUS FROM TEMP;

code.setup:
CREATE TABLE TEMP (SID INTEGER, NAME VARCHAR(10), DEGREE REAL, WEIGHT REAL);
INSERT INTO TEMP VALUES (1,'Amy',98.6,50);
INSERT INTO TEMP VALUES (2,'Bob',100.4,60);
INSERT INTO TEMP VALUES (3,'Cat',97.7,-3);

