code.src:
UPDATE EXP SET ACCEL = DIST * 2 / (TTIME * TTIME);
SELECT RID, ROUND(ACCEL, 3) AS ACCEL,
       ROUND(FORCE / ACCEL, 2) AS MASS
FROM EXP
ORDER BY MASS;

code.setup:
